// Template-backed family modules: the structure comes from a transcribed spec (specs/<id>.mjs, generated by
// tools/transcribe.mjs from config/package3d); `simMaterials` attaches library-key params to parts / layers whose
// template material is `other`; `edit(spec, P)` applies knob-driven structure changes.
// Solder-resist layers (element name "Solder resist ...", template material polymer_dielectric) get the sim key param
// `sr_mat` (library solder_resist; L9 2026-10-20: the polymer_dielectric alias maps them to polyimide_rdl, so a case
// override of solder_resist reached no part).
import { SIM_MAT } from './common.mjs';

const SR_NAME = /solder[ -]resist/i;
const isSR = (el) => SR_NAME.test(el.name ?? '') && el.material === 'polymer_dielectric';

/** Point every solder-resist layer element of a (cloned) spec at the `sr_mat` param; returns the spec. */
export function mapSolderResist(spec) {
  for (const g of spec.layers ?? []) for (const el of g.pattern ?? []) if (isSR(el) && !el.material_sim) el.material_sim = 'sr_mat';
  return spec;
}

export function templateFamily(spec, { ext = {}, layout = {}, preChecks = [], edit = null, simMaterials = {} } = {}) {
  const hasSR = (spec.layers ?? []).some((g) => (g.pattern ?? []).some(isSR));
  const ext2 = hasSR && !ext.add?.sr_mat ? { ...ext, add: { ...(ext.add ?? {}), sr_mat: SIM_MAT.sr_mat } } : ext;
  return {
    ext: ext2,
    layout,
    preChecks,
    build(P) {
      const s = JSON.parse(JSON.stringify({ parts: spec.parts, layers: spec.layers, arrays: spec.arrays }));
      for (const p of s.parts) if (simMaterials.parts?.[p.id]) p.material_sim = simMaterials.parts[p.id];
      for (const g of s.layers) {
        for (const el of g.pattern) {
          if (simMaterials.layers?.[el.id]) el.material_sim = simMaterials.layers[el.id];
          else if (hasSR && isSR(el)) el.material_sim = 'sr_mat';
          if (el.route && el.route.matrix === 'other' && simMaterials.matrix) el.route.matrix_sim = simMaterials.matrix;
        }
      }
      return edit ? edit(s, P) : s;
    },
    source: { template: spec.source_template, package3d_generated: spec.package3d_generated, transcriber: spec.transcriber },
  };
}

/** Edit helpers on a cloned transcribed spec. Every lookup throws when the template no longer has the id. */
export function editor(spec) {
  const find = (list, id, what) => {
    const i = list.findIndex((x) => x.id === id);
    if (i < 0) throw new Error(`template edit: ${what} ${id} not in the transcribed spec (template changed? re-check the family edit)`);
    return i;
  };
  return {
    spec,
    part: (id) => spec.parts[find(spec.parts, id, 'part')],
    hasPart: (id) => spec.parts.some((p) => p.id === id),
    array: (id) => spec.arrays[find(spec.arrays, id, 'array')],
    removeParts: (...ids) => { for (const id of ids) spec.parts.splice(find(spec.parts, id, 'part'), 1); },
    removeArrays: (...ids) => { for (const id of ids) spec.arrays.splice(find(spec.arrays, id, 'array'), 1); },
    replacePart: (id, decls) => { const i = find(spec.parts, id, 'part'); spec.parts.splice(i, 1, ...decls); },
    insertPartsAfter: (id, decls) => { const i = find(spec.parts, id, 'part'); spec.parts.splice(i + 1, 0, ...decls); },
    addParts: (...decls) => spec.parts.push(...decls),
    addArrays: (...decls) => spec.arrays.push(...decls),
    layerGroups: (host) => spec.layers.filter((g) => g.part === host),
    removeLayerHost: (host) => { spec.layers = spec.layers.filter((g) => g.part !== host); },
    layerEl: (id) => {
      for (const g of spec.layers) for (const el of g.pattern) if (el.id === id) return el;
      throw new Error(`template edit: layer ${id} not in the transcribed spec`);
    },
    /** Copy the layer groups of `host` onto `newHost`, renaming element ids prefix `from` -> `to`. */
    cloneLayers: (host, newHost, from, to) => {
      const groups = spec.layers.filter((g) => g.part === host);
      if (!groups.length) throw new Error(`template edit: no layer groups on ${host}`);
      for (const g of groups) {
        const c = JSON.parse(JSON.stringify(g));
        c.part = newHost;
        if (c.id) c.id = c.id.replace(from, to);
        for (const el of c.pattern) {
          if (!el.id.startsWith(from)) throw new Error(`template edit: layer ${el.id} does not start with ${from}`);
          el.id = to + el.id.slice(from.length);
        }
        spec.layers.push(c);
      }
    },
  };
}
